CREATE TABLE `payment_tbl` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `payment_id` text DEFAULT NULL,
  `user_id` text NOT NULL,
  `purchase_group_id` text NOT NULL,
  `user_id_menu` text NOT NULL,
  `payment_method` varchar(255) NOT NULL,
  `voucher_used_group_id` text DEFAULT NULL,
  `voucher_total_discounted_amount` decimal(30,2) NOT NULL DEFAULT 0.00,
  `total_discounted_amount` decimal(30,2) NOT NULL DEFAULT 0.00 COMMENT 'This column count only how many discount amount not included any computation',
  `total_amount` decimal(30,2) NOT NULL DEFAULT 0.00,
  `final_total_amount` decimal(30,2) DEFAULT NULL COMMENT 'This column use only if voucher_used_group_id and voucher_total_discounted_amount have value. \n                                    the computation is (voucher_total_discounted_amount - total_amount) = final_total_amount',
  `money` decimal(30,2) NOT NULL DEFAULT 0.00,
  `change` decimal(30,2) NOT NULL DEFAULT 0.00,
  `status` varchar(255) NOT NULL DEFAULT 'NOT PAID',
  `paid_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

